 if min(s,q)<0:return 0
 if s==0:return int(q==j==0)
 return c(n-q,s)*c(s+q-1,q)*c(2*s,j-q)
def g(n,i,s,p):
 if min(s,p)<0:return 0
 if s==0:return int(p==i==n)
 return c(s+p,p)*c(n-p-1,s-1)*c(2*s,i-p)
